/**
 * Where the SEV device private keys live. SW-76 (2025-06) §4.2.1 asks a SEV in mode SEV for a NON-EXPORTABLE private key.
 *
 *  - software: generated by Node, sealed AES-256-GCM in the database (KeyVault). Exportable by whoever holds
 *    PRIVATE_KEY_ENCRYPTION_KEY: SIMULATOR / DEV / ESSAI only (app-config refuses it in PROD).
 *  - gcp-kms:  generated and kept inside Google Cloud KMS (protection level HSM in PROD): gcp-kms.ts. QCMEV stores only
 *    the key's name, sealed like a software key, and asks KMS for every signature. The key never leaves KMS.
 *
 * Both are stored in Certificate.encryptedPrivateKey (no schema change): the sealed value says which one it is, so a
 * device keeps working with the key it was certified with. Every signature from a remote key is verified with the key's
 * public key before it is used: a wrong or corrupted answer never goes out.
 */
import * as crypto from 'crypto';
import { signP256 } from './ecdsa';
import { KeyVault } from './key-vault';

export type KeyCustodyKind = 'software' | 'gcp-kms';

/** A device key that can sign: ECDSA P-256 / SHA-256, signature r||s (64 bytes, IEEE P1363). */
export interface SevSigner {
  readonly kind: KeyCustodyKind;
  readonly publicKey: crypto.KeyObject;
  /** The signature of `data`, base64 (88 characters): signa.actu, SIGNATRANSM. */
  sign(data: string | Buffer): Promise<string>;
  /** Raw r||s (the CSR signature). */
  signP1363(data: Buffer): Promise<Buffer>;
}

/** A key just created for one device certificate, with the value to store for it. */
export interface NewSevKey extends SevSigner {
  /** Stored in Certificate.encryptedPrivateKey. */
  readonly sealed: string;
}

export interface SevKeyCustody {
  readonly kind: KeyCustodyKind;
  createKey(deviceId: string): Promise<NewSevKey>;
  /** The signer of a stored key (software or KMS, whatever the current setting: a device keeps its key). */
  open(sealed: string, deviceId: string): Promise<SevSigner>;
  /** What a stored key is, without opening it. */
  kindOf(sealed: string, deviceId: string): KeyCustodyKind;
  /** The key replaced by a renewal (CRT REM): KMS disables its version; a software key has nothing to do. */
  retire(sealed: string, deviceId: string): Promise<void>;
}

export const KEY_CUSTODY = Symbol('KEY_CUSTODY');

/** Sealed KMS key: "kms:gcp:" + the full CryptoKeyVersion name. */
export const GCP_KMS_PREFIX = 'kms:gcp:';

export const keyContext = (deviceId: string) => `key:${deviceId}`;

/** DER ECDSA signature (SEQUENCE { INTEGER r, INTEGER s }) → r||s, 32 bytes each. */
export function derToP1363(der: Buffer): Buffer {
  let i = 0;
  const fail = (): never => {
    throw new Error('invalid DER ECDSA signature');
  };
  if (der[i++] !== 0x30) fail();
  let seqLen = der[i++];
  if (seqLen & 0x80) {
    const n = seqLen & 0x7f;
    if (n !== 1) fail();
    seqLen = der[i++];
  }
  if (i + seqLen !== der.length) fail();
  const int = (): Buffer => {
    if (der[i++] !== 0x02) fail();
    const len = der[i++];
    if (!len || len > 33 || i + len > der.length) fail();
    let v = der.subarray(i, i + len);
    i += len;
    while (v.length > 32 && v[0] === 0) v = v.subarray(1);
    if (v.length > 32) fail();
    return Buffer.concat([Buffer.alloc(32 - v.length), v]);
  };
  const r = int();
  const s = int();
  if (i !== der.length) fail();
  return Buffer.concat([r, s]);
}

/** A signer from a key object (software keys; also the fake KMS in tests). */
export function softwareSigner(privateKey: crypto.KeyObject | string): SevSigner {
  const key = typeof privateKey === 'string' ? crypto.createPrivateKey(privateKey) : privateKey;
  return {
    kind: 'software',
    publicKey: crypto.createPublicKey(key),
    sign: async (data) => signP256(key, data),
    signP1363: async (data) => Buffer.from(signP256(key, data), 'base64'),
  };
}

/** Software custody: today's keys (SIMULATOR / DEV / ESSAI). */
export class SoftwareKeyCustody implements SevKeyCustody {
  readonly kind = 'software' as const;

  constructor(private readonly vault: KeyVault) {}

  async createKey(deviceId: string): Promise<NewSevKey> {
    const { privateKey } = crypto.generateKeyPairSync('ec', { namedCurve: 'P-256' });
    const pem = privateKey.export({ type: 'pkcs8', format: 'pem' }).toString();
    return { ...softwareSigner(privateKey), sealed: this.vault.encrypt(pem, keyContext(deviceId)) };
  }

  async open(sealed: string, deviceId: string): Promise<SevSigner> {
    const plain = this.vault.decrypt(sealed, keyContext(deviceId));
    if (plain.startsWith(GCP_KMS_PREFIX)) throw new Error('this device key is held in Google Cloud KMS: set SEV_KEY_CUSTODY=gcp-kms');
    return softwareSigner(plain);
  }

  kindOf(sealed: string, deviceId: string): KeyCustodyKind {
    return this.vault.decrypt(sealed, keyContext(deviceId)).startsWith(GCP_KMS_PREFIX) ? 'gcp-kms' : 'software';
  }

  async retire(): Promise<void> {
    // The certificate row is deactivated; its sealed key is never used again.
  }
}
